// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement"
// Changes: Prove a fixed-size natural loop has an invariant bound and one
// unit-stride update.
#include "optimizer_induction.h"
#include "optimizer_helpers.h"
#include "optimizer_loop_internal.h"

/**
 * @brief Collect the explicit successor block IDs from a terminator.
 *
 * @param term Block terminator to inspect.
 * @param targets Output buffer for up to two successor IDs.
 * @return Number of successor IDs written.
 */
static size_t edges(const IrBlockTerminator* term, IrBlockId targets[2]) {
  if (term->type == IR_TERMINATOR_JUMP) {
    targets[0] = term->value.jump_target;
    return 1;
  }

  if (term->type == IR_TERMINATOR_CONDITIONAL) {
    targets[0] = term->value.conditional_target.true_target;
    targets[1] = term->value.conditional_target.false_target;
    return 2;
  }

  return 0;
}

/**
 * @brief Mark blocks reachable through the candidate loop body up to its
 * boundary.
 *
 * @param fn IR function under analysis.
 * @param loop Loop descriptor receiving membership flags.
 * @param id Block whose successors are explored.
 */
static void mark_members(const IrFunction* fn,
                         InductionLoop* loop,
                         IrBlockId id) {
  if (id == loop->head || id == loop->exit || loop->member[id])
    return;

  loop->member[id] = true;
  IrBlockId targets[2];
  size_t count = edges(&fn->blocks.data[id].terminator, targets);

  for (size_t i = 0; i < count; i++)
    mark_members(fn, loop, targets[i]);
}

/**
 * @brief Identify the load instruction matching a candidate value or slot.
 *
 * @param fn IR function under analysis.
 * @param operand Operand to inspect.
 * @param slot Stack slot to inspect.
 * @return True if the operand loads the requested slot.
 */
static bool load_of(IrFunction* fn, IrOperand operand, IrStackSlotId slot) {
  if (operand.type != IR_OP_VALUE)
    return false;

  const IrInstruction* load = optimizer_find_definition(fn, operand.value.id);
  return load && load->type == IR_INST_LOAD &&
         load->operands.load.source == slot;
}

/**
 * @brief Recognize the final unit-stride increment and store in the loop latch.
 *
 * @param fn IR function under analysis.
 * @param block Block or instruction list under analysis.
 * @param slot Stack slot to inspect.
 * @param step Signed unit stride.
 * @param header_index SSA value ID of the header index load.
 * @return True if the latch ends with the required unit advance.
 */
static bool is_advance(IrFunction* fn,
                       const IrInstructionArray* block,
                       IrStackSlotId slot,
                       IrInt step,
                       IrValueId header_index) {
  if (block->count < 2)
    return false;

  const IrInstruction* add = &block->data[block->count - 2];
  const IrInstruction* store = &block->data[block->count - 1];
  if (add->type != IR_INST_ADD)
    return false;

  bool current =
      optimizer_loop_direct_use(add->operands.binary.left, header_index);

  for (size_t i = 0; i + 2 < block->count; i++)
    if (block->data[i].type == IR_INST_LOAD &&
        block->data[i].operands.load.source == slot &&
        optimizer_loop_direct_use(add->operands.binary.left,
                                  block->data[i].result))
      current = true;

  return current && add->type == IR_INST_ADD &&
         add->operands.binary.right.type == IR_OP_INT32 &&
         add->operands.binary.right.value.int32_value == step &&
         load_of(fn, add->operands.binary.left, slot) &&
         store->type == IR_INST_STORE && store->operands.store.target == slot &&
         optimizer_loop_direct_use(store->operands.store.source, add->result);
}

bool optimizer_analyze_induction(IrFunction* fn,
                                 IrBlockId head,
                                 InductionLoop* loop) {
  if (fn->blocks.count > INDUCTION_BLOCKS || fn->entrypoint == head)
    return false;

  const IrBlock* header = &fn->blocks.data[head];
  if (header->terminator.type != IR_TERMINATOR_CONDITIONAL ||
      header->instructions.count < 2 || header->instructions.count > 3)
    return false;

  IrOperand condition = header->terminator.value.conditional_target.condition;
  IrInstruction* cmp =
      &header->instructions.data[header->instructions.count - 1];

  if (!optimizer_loop_direct_use(condition, cmp->result) ||
      (cmp->type != IR_INST_LT && cmp->type != IR_INST_GT))
    return false;

  const IrInstruction* index = &header->instructions.data[0];
  if (index->type != IR_INST_LOAD || index->result_type != IR_INT ||
      !optimizer_loop_direct_use(cmp->operands.binary.left, index->result))
    return false;

  *loop = (InductionLoop){
      .head = head,
      .pre = IR_INVALID_ID,
      .latch = IR_INVALID_ID,
      .body = header->terminator.value.conditional_target.true_target,
      .exit = header->terminator.value.conditional_target.false_target,
      .slot = index->operands.load.source,
      .comparison = cmp,
      .bound = cmp->operands.binary.right,
      .step = cmp->type == IR_INST_LT ? 1 : -1};

  if (loop->body == head || loop->exit == head || loop->body == loop->exit ||
      optimizer_loop_edge_count(fn, head) != 2)
    return false;

  // Classify the two incoming header edges as the preheader and the latch, and
  // rule out side entries.
  mark_members(fn, loop, loop->body);
  if (loop->member[fn->entrypoint])
    return false;

  for (IrBlockId b = 0; b < fn->blocks.count; b++) {
    const IrBlock* block = &fn->blocks.data[b];
    IrBlockId targets[2];
    size_t count = edges(&block->terminator, targets);

    for (size_t i = 0; i < count; i++) {
      IrBlockId target = targets[i];

      if (target == head) {
        if (!optimizer_loop_jumps_to(block, head))
          return false;

        if (loop->member[b])
          loop->latch = b;
        else
          loop->pre = b;
      } else if (loop->member[target] && !loop->member[b] && b != head)
        return false;
    }
  }

  if (loop->pre == IR_INVALID_ID || loop->latch == IR_INVALID_ID ||
      !is_advance(fn, &fn->blocks.data[loop->latch].instructions, loop->slot,
                  loop->step, index->result))
    return false;

  // The last store in the preheader must provide a literal initial index.
  const IrInstructionArray* pre = &fn->blocks.data[loop->pre].instructions;
  const IrOperand* start = NULL;
  for (size_t i = 0; i < pre->count; i++)
    if (pre->data[i].type == IR_INST_STORE &&
        pre->data[i].operands.store.target == loop->slot)
      start = &pre->data[i].operands.store.source;

  if (!start || start->type != IR_OP_INT32)
    return false;

  loop->start = start->value.int32_value;

  // A dynamic bound must be defined before the loop or loaded from an
  // initialized invariant slot.
  if (loop->bound.type == IR_OP_VALUE) {
    if (header->instructions.count == 3) {
      const IrInstruction* bound = &header->instructions.data[1];

      if (bound->type != IR_INST_LOAD || bound->result_type != IR_INT ||
          !optimizer_loop_direct_use(loop->bound, bound->result))
        return false;

      loop->bound_load = bound;
      bool initialized = bound->operands.load.source < fn->parameter_count;
      for (size_t i = 0; i < pre->count; i++)
        if (pre->data[i].type == IR_INST_STORE &&
            pre->data[i].operands.store.target == bound->operands.load.source)
          initialized = true;

      if (!initialized)
        return false;
    } else {
      bool defined = false;

      for (size_t i = 0; i < pre->count; i++)
        if (pre->data[i].result == loop->bound.value.id &&
            pre->data[i].result_type == IR_INT)
          defined = true;

      if (!defined)
        return false;
    }
  } else if (loop->bound.type != IR_OP_INT32 || header->instructions.count != 2)
    return false;

  // Reject every competing index or bound store in the loop before handing the
  // proof to the rewrites.
  for (IrBlockId b = 0; b < fn->blocks.count; b++) {
    if (!loop->member[b])
      continue;

    const IrInstructionArray* ins = &fn->blocks.data[b].instructions;

    for (size_t i = 0; i < ins->count; i++) {
      const IrInstruction* inst = &ins->data[i];

      if (inst->type != IR_INST_STORE)
        continue;

      IrStackSlotId target = inst->operands.store.target;
      if ((target == loop->slot && (b != loop->latch || i + 1 != ins->count)) ||
          (loop->bound_load &&
           target == loop->bound_load->operands.load.source))
        return false;
    }
  }

  return true;
}
